// 48h hourly temperature sparkline
const draw = (ctx, { width: w, height: h }) => {
  ctx.fillStyle = "#242331";
  ctx.fillRect(0, 0, w, h);
  const t = fc?.hourly?.temperature_2m?.slice(0, 48);
  ctx.font = "10px monospace";
  if (!t || t.length < 2) {
    ctx.fillStyle = "#8b89a0";
    ctx.fillText("waiting for forecast…", 10, h / 2);
    return;
  }
  const lo = Math.min(...t);
  const hi = Math.max(...t);
  const y = (v) => h - 16 - ((v - lo) / (hi - lo || 1)) * (h - 34);
  ctx.strokeStyle = "#d9a13f";
  ctx.lineWidth = 1.5;
  ctx.beginPath();
  t.forEach((v, i) => {
    const x = 6 + (i / (t.length - 1)) * (w - 12);
    i ? ctx.lineTo(x, y(v)) : ctx.moveTo(x, y(v));
  });
  ctx.stroke();
  ctx.fillStyle = "#8b89a0";
  ctx.fillText(`next 48h · ${lo}° … ${hi}°`, 8, 13);
};
draw;
